import * as React from 'react';
import { expect, vi, it } from 'vitest';
import { createRenderer, fireEvent, screen, act } from '@mui/internal-test-utils';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';

const { render } = createRenderer();

it('disabled while loading then enabled', async () => {
  function App({ loaded, disabled }: any) {
    return (
      <Field.Root data-testid="root" disabled={disabled}>
        <Field.Control value={loaded} onValueChange={() => {}} />
      </Field.Root>
    );
  }
  const { setProps } = await render(<App loaded="" disabled />);
  const root = screen.getByTestId('root');
  await setProps({ loaded: 'Alice', disabled: true });
  console.log('A after load disabled: dirty', root.hasAttribute('data-dirty'));
  await setProps({ loaded: 'Alice', disabled: false });
  console.log('A after enable: dirty', root.hasAttribute('data-dirty'));
});

it('enabled loading then async', async () => {
  function App({ loaded }: any) {
    return (
      <Field.Root data-testid="root">
        <Field.Control value={loaded} onValueChange={() => {}} />
      </Field.Root>
    );
  }
  const { setProps } = await render(<App loaded="" />);
  await setProps({ loaded: 'Alice' });
  console.log('B dirty', screen.getByTestId('root').hasAttribute('data-dirty'));
});

it('focus latch on disable', async () => {
  function App({ disabled }: any) {
    return (
      <Field.Root data-testid="root">
        <Field.Control disabled={disabled} />
      </Field.Root>
    );
  }
  const { setProps } = await render(<App disabled={false} />);
  act(() => screen.getByRole('textbox').focus());
  console.log('C focused', screen.getByTestId('root').hasAttribute('data-focused'));
  await setProps({ disabled: true });
  console.log('C after disable focused', screen.getByTestId('root').hasAttribute('data-focused'));
});

it('submit validate arg', async () => {
  const validate = vi.fn(() => null);
  await render(
    <Form>
      <Field.Root name="n" validate={validate}>
        <Field.Control value={5} onValueChange={() => {}} />
      </Field.Root>
      <button type="submit">s</button>
    </Form>,
  );
  fireEvent.click(screen.getByRole('button'));
  console.log('D validate args', JSON.stringify(validate.mock.calls));
});

it('controlled-defaultPrevented clears server error', async () => {
  const validate = vi.fn(() => null);
  function App() {
    const [v, setV] = React.useState('');
    return (
      <Form errors={{ message: 'Server error' }}>
        <Field.Root name="message" validationMode="onChange" validate={validate}>
          <Field.Control value={v} onValueChange={setV} />
          <Field.Error />
        </Field.Root>
      </Form>
    );
  }
  await render(<App />);
  const control = screen.getByRole<HTMLInputElement>('textbox');
  control.addEventListener('input', (e) => e.preventDefault(), { capture: true, once: true });
  fireEvent.input(control, { cancelable: true, target: { value: 'a' } });
  console.log('E validate calls', validate.mock.calls.length, 'err shown', !!screen.queryByText('Server error'));
});
EOF
